// Package water 是本地取样与超标判定的本地基线。
package water

// Ready 表示基线可以运行。
func Ready() bool { return true }

content.content:
1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io/fs"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"sync"
14		"time"
15	)
16	
17	// Status 表示样品所处的判定状态。
18	type Status string
19	
20	const (
21		// StatusPending 样品已录入，尚未确认判定结果。
22		StatusPending Status = "pending"
23		// StatusConfirmed 样品已确认，判定结果已保存。
24		StatusConfirmed Status = "confirmed"
25		// StatusVoided 样品已作废，保留记录但不能再确认。
26		StatusVoided Status = "voided"
27	)
28	
29	var (
30		ErrClosed             = errors.New("water: 数据存放已关闭")
31		ErrEmptyField         = errors.New("water: 编号、名称或项目去掉首尾空白后不能为空")
32		ErrDuplicatePoint     = errors.New("water: 采样点编号已登记")
33		ErrUnknownPoint       = errors.New("water: 采样点未登记")
34		ErrInvalidValue       = errors.New("water: 数值只接受有限数")
35		ErrInvalidTime        = errors.New("water: 采样时间或生效时间缺失")
36		ErrDuplicateLimitTime = errors.New("water: 同一采样点同一项目已存在相同生效时间的上限")
37		ErrUnknownSample      = errors.New("water: 样品编号不存在")
38		ErrSampleConflict     = errors.New("water: 同一编号提交的样品内容不一致")
39		ErrDuplicateItem      = errors.New("water: 同一份样品的测量项目重复")
40		ErrNoMeasurements     = errors.New("water: 样品至少需要一个项目的测量值")
41		ErrMissingLimit       = errors.New("water: 存在找不到适用上限的测量项目")
42		ErrVoided             = errors.New("water: 样品已作废，不能再确认")
43		ErrVoidReasonConflict = errors.New("water: 作废原因与已有记录不一致")
44	)
45	
46	// SamplingPoint 是按编号唯一登记的采样点。
47	type SamplingPoint struct {
48		ID   string `json:"id"`
49		Name string `json:"name"`
50	}
51	
52	// Limit 是某采样点某测量项目的一版数值上限。
53	type Limit struct {
54		PointID   string    `json:"pointId"`
55		Item      string    `json:"item"`
56		Value     float64   `json:"value"`
57		Effective time.Time `json:"effective"`
58	}
59	
60	// Measurement 是样品中一个项目的测量值。
61	type Measurement struct {
62		Item  string  `json:"item"`
63		Value float64 `json:"value"`
64	}
65	
66	// ItemResult 是确认后单个项目的判定结果。
67	type ItemResult struct {
68		Item           string    `json:"item"`
69		Value          float64   `json:"value"`
70		Limit          float64   `json:"limit"`
71		LimitEffective time.Time `json:"limitEffective"`
72		Exceeded       bool      `json:"exceeded"`
73	}
74	
75	// Sample 是一份从录入、确认到作废的样品记录。
76	type Sample struct {
77		ID           string        `json:"id"`
78		PointID      string        `json:"pointId"`
79		SampledAt    time.Time     `json:"sampledAt"`
80		Measurements []Measurement `json:"measurements"`
81		Status       Status        `json:"status"`
82		Results      []ItemResult  `json:"results,omitempty"`
83		Exceeded     bool          `json:"exceeded"`
84		VoidReason   string        `json:"voidReason,omitempty"`
85	}
86	
87	// diskState 是落盘的完整数据。
88	type diskState struct {
89		Points  map[string]SamplingPoint `json:"points"`
90		Limits  map[string][]Limit       `json:"limits"`
91		Samples map[string]*Sample       `json:"samples"`
92	}
93	
94	// Store 是绑定到某个本地目录的取样判定数据存放。
95	// 不同目录的数据互不混用；关闭后重新打开仍能查看原有记录。
96	type Store struct {
97		mu      sync.Mutex
98		dir     string
99		file    string
100		closed  bool
101		points  map[string]SamplingPoint
102		limits  map[string][]Limit // key: pointID + "\x00" + item，按生效时间升序
103		samples map[string]*Sample
104	}
105	
106	// Open 打开（必要时创建）dir 下的本地数据存放。
107	func Open(dir string) (*Store, error) {
108		if strings.TrimSpace(dir) == "" {
109			return nil, fmt.Errorf("%w: 数据目录", ErrEmptyField)
110		}
111		if err := os.MkdirAll(dir, 0o755); err != nil {
112			return nil, err
113		}
114		s := &Store{
115			dir:     dir,
116			file:    filepath.Join(dir, "water-data.json"),
117			points:  map[string]SamplingPoint{},
118			limits:  map[string][]Limit{},
119			samples: map[string]*Sample{},
120		}
121		data, err := os.ReadFile(s.file)
122		if errors.Is(err, fs.ErrNotExist) {
123			return s, nil
124		}
125		if err != nil {
126			return nil, err
127		}
128		var st diskState
129		if err := json.Unmarshal(data, &st); err != nil {
130			return nil, fmt.Errorf("water: 读取数据文件失败: %w", err)
131		}
132		if st.Points != nil {
133			s.points = st.Points
134		}
135		if st.Limits != nil {
136			s.limits = st.Limits
137		}
138		if st.Samples != nil {
139			s.samples = st.Samples
140		}
141		return s, nil
142	}
143	
144	// Close 关闭数据存放。已保存的记录已落盘，重新 Open 同一目录即可查看。
145	func (s *Store) Close() error {
146		s.mu.Lock()
147		defer s.mu.Unlock()
148		if s.closed {
149			return nil
150		}
151		s.closed = true
152		return nil
153	}
154	
155	func clean(s string) string { return strings.TrimSpace(s) }
156	
157	func limitKey(pointID, item string) string { return pointID + "\x00" + item }
158	
159	func finite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
160	
161	func (s *Store) checkOpenLocked() error {
162		if s.closed {
163			return ErrClosed
164		}
165		return nil
166	}
167	
168	// persistLocked 把全部数据原子写回数据文件。只在成功变更后调用，
169	// 被拒绝的操作不会走到这里，因此不会留下新增或变更记录。
170	func (s *Store) persistLocked() error {
171		data, err := json.MarshalIndent(diskState{
172			Points:  s.points,
173			Limits:  s.limits,
174			Samples: s.samples,
175		}, "", "  ")
176		if err != nil {
177			return err
178		}
179		tmp := s.file + ".tmp"
180		if err := os.WriteFile(tmp, data, 0o644); err != nil {
181			return err
182		}
183		return os.Rename(tmp, s.file)
184	}
185	
186	// RegisterPoint 登记采样点。编号、名称去掉首尾空白后不能为空，
187	// 保存和比较均使用处理后的文本；重复编号拒绝。
188	func (s *Store) RegisterPoint(id, name string) (SamplingPoint, error) {
189		s.mu.Lock()
190		defer s.mu.Unlock()
191		if err := s.checkOpenLocked(); err != nil {
192			return SamplingPoint{}, err
193		}
194		id, name = clean(id), clean(name)
195		if id == "" || name == "" {
196			return SamplingPoint{}, ErrEmptyField
197		}
198		if _, ok := s.points[id]; ok {
199			return SamplingPoint{}, fmt.Errorf("%w: %s", ErrDuplicatePoint, id)
200		}
201		p := SamplingPoint{ID: id, Name: name}
202		s.points[id] = p
203		if err := s.persistLocked(); err != nil {
204			delete(s.points, id)
205			return SamplingPoint{}, err
206		}
207		return p, nil
208	}
209	
210	// SetLimit 为已登记采样点的某个测量项目登记一版数值上限及生效时间。
211	// 允许乱序补录；生效时间相同（不同时区表示的同一时刻也算相同）的第二条拒绝。
212	func (s *Store) SetLimit(pointID, item string, value float64, effective time.Time) (Limit, error) {
213		s.mu.Lock()
214		defer s.mu.Unlock()
215		if err := s.checkOpenLocked(); err != nil {
216			return Limit{}, err
217		}
218		pointID, item = clean(pointID), clean(item)
219		if pointID == "" || item == "" {
220			return Limit{}, ErrEmptyField
221		}
222		if _, ok := s.points[pointID]; !ok {
223			return Limit{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
224		}
225		if !finite(value) {
226			return Limit{}, ErrInvalidValue
227		}
228		if effective.IsZero() {
229			return Limit{}, ErrInvalidTime
230		}
231		lim := Limit{PointID: pointID, Item: item, Value: value, Effective: effective.UTC()}
232		key := limitKey(pointID, item)
233		versions := s.limits[key]
234		for _, v := range versions {
235			if v.Effective.Equal(lim.Effective) {
236				return Limit{}, fmt.Errorf("%w: %s/%s @ %s", ErrDuplicateLimitTime, pointID, item, lim.Effective)
237			}
238		}
239		old := s.limits[key]
240		// 复制到新切片再插入排序：append/sort 会原地改动共享底层数组，
241		// 一旦保存失败需要回滚，old 必须仍是调用前的完整状态。
242		versions = make([]Limit, len(old)+1)
243		copy(versions, old)
244		versions[len(old)] = lim
245		sort.Slice(versions, func(i, j int) bool { return versions[i].Effective.Before(versions[j].Effective) })
246		s.limits[key] = versions
247		if err := s.persistLocked(); err != nil {
248			s.limits[key] = old
249			return Limit{}, err
250		}
251		return lim, nil
252	}
253	
254	// SubmitSample 录入一份样品，初始为待判定状态。
255	// 再次提交同一编号且内容相同（项目排列顺序不同不算变化）返回原样品；
256	// 任一内容不同则拒绝整个提交，已确认或已作废的样品同样遵守。
257	func (s *Store) SubmitSample(id, pointID string, sampledAt time.Time, measurements ...Measurement) (Sample, error) {
258		s.mu.Lock()
259		defer s.mu.Unlock()
260		if err := s.checkOpenLocked(); err != nil {
261			return Sample{}, err
262		}
263		id, pointID = clean(id), clean(pointID)
264		if id == "" || pointID == "" {
265			return Sample{}, ErrEmptyField
266		}
267		if sampledAt.IsZero() {
268			return Sample{}, ErrInvalidTime
269		}
270		if len(measurements) == 0 {
271			return Sample{}, ErrNoMeasurements
272		}
273		ms := make([]Measurement, len(measurements))
274		seen := make(map[string]float64, len(measurements))
275		for i, m := range measurements {
276			item := clean(m.Item)
277			if item == "" {
278				return Sample{}, ErrEmptyField
279			}
280			if !finite(m.Value) {
281				return Sample{}, ErrInvalidValue
282			}
283			if _, dup := seen[item]; dup {
284				return Sample{}, fmt.Errorf("%w: %s", ErrDuplicateItem, item)
285			}
286			seen[item] = m.Value
287			ms[i] = Measurement{Item: item, Value: m.Value}
288		}
289		sampledAt = sampledAt.UTC()
290	
291		if existing, ok := s.samples[id]; ok {
292			if sameSampleContent(existing, pointID, sampledAt, seen) {
293				return copySample(existing), nil
294			}
295			return Sample{}, fmt.Errorf("%w: %s", ErrSampleConflict, id)
296		}
297		if _, ok := s.points[pointID]; !ok {
298			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownPoint, pointID)
299		}
300		smp := &Sample{
301			ID:           id,
302			PointID:      pointID,
303			SampledAt:    sampledAt,
304			Measurements: ms,
305			Status:       StatusPending,
306		}
307		s.samples[id] = smp
308		if err := s.persistLocked(); err != nil {
309			delete(s.samples, id)
310			return Sample{}, err
311		}
312		return copySample(smp), nil
313	}
314	
315	func sameSampleContent(s *Sample, pointID string, sampledAt time.Time, ms map[string]float64) bool {
316		if s.PointID != pointID || !s.SampledAt.Equal(sampledAt) || len(s.Measurements) != len(ms) {
317			return false
318		}
319		for _, m := range s.Measurements {
320			v, ok := ms[m.Item]
321			if !ok || v != m.Value {
322				return false
323			}
324		}
325		return true
326	}
327	
328	// Confirm 确认一份待判定样品：每个项目取生效时间不晚于采样时间的最近一版上限，
329	// 测量值大于上限才超标，任一项目超标则整份样品超标。
330	// 只要有项目找不到适用上限，本次确认拒绝，样品保持待判定。
331	// 重复确认直接返回已保存结果；之后新增或补录限值不改变已确认结果。
332	func (s *Store) Confirm(id string) (Sample, error) {
333		s.mu.Lock()
334		defer s.mu.Unlock()
335		if err := s.checkOpenLocked(); err != nil {
336			return Sample{}, err
337		}
338		id = clean(id)
339		if id == "" {
340			return Sample{}, ErrEmptyField
341		}
342		smp, ok := s.samples[id]
343		if !ok {
344			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
345		}
346		switch smp.Status {
347		case StatusVoided:
348			return Sample{}, fmt.Errorf("%w: %s", ErrVoided, id)
349		case StatusConfirmed:
350			return copySample(smp), nil
351		}
352	
353		results := make([]ItemResult, 0, len(smp.Measurements))
354		exceeded := false
355		for _, m := range smp.Measurements {
356			lim, ok := applicableLimit(s.limits[limitKey(smp.PointID, m.Item)], smp.SampledAt)
357			if !ok {
358				return Sample{}, fmt.Errorf("%w: 样品 %s 的项目 %s", ErrMissingLimit, id, m.Item)
359			}
360			ex := m.Value > lim.Value
361			if ex {
362				exceeded = true
363			}
364			results = append(results, ItemResult{
365				Item:           m.Item,
366				Value:          m.Value,
367				Limit:          lim.Value,
368				LimitEffective: lim.Effective,
369				Exceeded:       ex,
370			})
371		}
372		smp.Results = results
373		smp.Exceeded = exceeded
374		smp.Status = StatusConfirmed
375		if err := s.persistLocked(); err != nil {
376			smp.Results = nil
377			smp.Exceeded = false
378			smp.Status = StatusPending
379			return Sample{}, err
380		}
381		return copySample(smp), nil
382	}
383	
384	// applicableLimit 在按生效时间升序的版本里取不晚于 at 的最近一版；
385	// 采样时间恰好等于生效时间时使用该版新值。
386	func applicableLimit(versions []Limit, at time.Time) (Limit, bool) {
387		best := -1
388		for i, v := range versions {
389			if v.Effective.After(at) {
390				break
391			}
392			best = i
393		}
394		if best < 0 {
395			return Limit{}, false
396		}
397		return versions[best], true
398	}
399	
400	// Void 作废样品。原因去掉首尾空白后不能为空；待判定和已确认的样品都能作废。
401	// 作废后保留测量、原因和已有结果；重复提交处理后相同的原因返回原记录，不同则拒绝。
402	func (s *Store) Void(id, reason string) (Sample, error) {
403		s.mu.Lock()
404		defer s.mu.Unlock()
405		if err := s.checkOpenLocked(); err != nil {
406			return Sample{}, err
407		}
408		id, reason = clean(id), clean(reason)
409		if id == "" || reason == "" {
410			return Sample{}, ErrEmptyField
411		}
412		smp, ok := s.samples[id]
413		if !ok {
414			return Sample{}, fmt.Errorf("%w: %s", ErrUnknownSample, id)
415		}
416		if smp.Status == StatusVoided {
417			if smp.VoidReason == reason {
418				return copySample(smp), nil
419			}
420			return Sample{}, fmt.Errorf("%w: %s", ErrVoidReasonConflict, id)
421		}
422		oldStatus := smp.Status
423		smp.Status = StatusVoided
424		smp.VoidReason = reason
425		if err := s.persistLocked(); err != nil {
426			smp.Status = oldStatus
427			smp.VoidReason = ""
428			return Sample{}, err
429		}
430		return copySample(smp), nil
431	}
432	
433	// ListByPoint 按采样点查看样品，按采样时间从晚到早排列，同一时刻按样品编号升序。
434	func (s *Store) ListByPoint(pointID string) ([]Sample, error) {
435		s.mu.Lock()
436		defer s.mu.Unlock()
437		if err := s.checkOpenLocked(); err != nil {
438			return nil, err
439		}
440		pointID = clean(pointID)
441		var list []Sample
442		for _, smp := range s.samples {
443			if smp.PointID == pointID {
444				list = append(list, copySample(smp))
445			}
446		}
447		sortSamples(list)
448		return list, nil
449	}
450	
451	// LatestResult 返回该采样点最近有效的已确认样品（跳过待判定与已作废）。
452	// 没有已确认且未作废的样品时 ok 为 false。
453	func (s *Store) LatestResult(pointID string) (smp Sample, ok bool, err error) {
454		s.mu.Lock()
455		defer s.mu.Unlock()
456		if err := s.checkOpenLocked(); err != nil {
457			return Sample{}, false, err
458		}
459		pointID = clean(pointID)
460		var list []Sample
461		for _, s := range s.samples {
462			if s.PointID == pointID && s.Status == StatusConfirmed {
463				list = append(list, copySample(s))
464			}
465		}
466		if len(list) == 0 {
467			return Sample{}, false, nil
468		}
469		sortSamples(list)
470		return list[0], true, nil
471	}
472	
473	func sortSamples(list []Sample) {
474		sort.Slice(list, func(i, j int) bool {
475			a, b := list[i], list[j]
476			if !a.SampledAt.Equal(b.SampledAt) {
477				return a.SampledAt.After(b.SampledAt)
478			}
479			return a.ID < b.ID
480		})
481	}
482	
483	func copySample(s *Sample) Sample {
484		c := *s
485		c.Measurements = append([]Measurement(nil), s.Measurements...)
486		c.Results = append([]ItemResult(nil), s.Results...)
487		return c
488	}
489

