289			t.Fatalf("rejected confirm must leave sample pending without partial results: %+v", list)
290		}
291	
292		// 补齐限值后可再次确认
293		mustLimit(t, s, "P1", "SS", 15.0, at(1, 0))
294		smp1, err := s.Confirm("S1")
295		if err != nil {
296			t.Fatalf("Confirm after backfill: %v", err)
297		}
298		if smp1.Status != StatusConfirmed || !smp1.Exceeded {
299			t.Fatalf("expected confirmed & exceeded, got %+v", smp1)
300		}
301		// pH 取不晚于采样时间的最近一版（7.0@09-10），7.5 超标；SS 10 ≤ 15 达标
302		if smp1.Results[0].Limit != 7.0 || !smp1.Results[0].Exceeded {
303			t.Fatalf("pH result wrong: %+v", smp1.Results[0])
304		}
305		if smp1.Results[1].Limit != 15.0 || smp1.Results[1].Exceeded {
306			t.Fatalf("SS result wrong: %+v", smp1.Results[1])
307		}
308	
309		// 采样时间恰好等于生效时间时使用新值
310		mustSample(t, s, "S2", "P1", at(10, 0), Measurement{Item: "pH", Value: 7.5})
311		smp2, err := s.Confirm("S2")
312		if err != nil {
313			t.Fatalf("Confirm S2: %v", err)
314		}
315		if smp2.Results[0].Limit != 7.0 || !smp2.Results[0].LimitEffective.Equal(at(10, 0)) {
316			t.Fatalf("boundary effective time should use new value, got %+v", smp2.Results[0])
317		}
318		if !smp2.Exceeded {
319			t.Fatalf("7.5 > 7.0 should exceed")
320		}
321	
322		// 等于上限算达标
323		mustSample(t, s, "S3", "P1", at(11, 0), Measurement{Item: "pH", Value: 7.0})
324		smp3, _ := s.Confirm("S3")
325		if smp3.Exceeded || smp3.Results[0].Exceeded {
326			t.Fatalf("equal to limit should pass, got %+v", smp3.Results[0])
327		}
328	
329		// 重复确认直接返回已保存结果；之后补录限值不改变已确认结果
330		mustLimit(t, s, "P1", "pH", 100.0, at(10, 12))
331		again, err := s.Confirm("S2")
332		if err != nil {
333			t.Fatalf("re-confirm: %v", err)
334		}
335		if again.Results[0].Limit != 7.0 || !again.Exceeded {
336			t.Fatalf("confirmed result must not change, got %+v", again.Results[0])
337		}
338	
339		if _, err := s.Confirm("nope"); !errors.Is(err, ErrUnknownSample) {
340			t.Fatalf("unknown sample, got %v", err)
341		}
