532	func TestVoid(t *testing.T) {
533		s, _ := open(t)
534		mustPoint(t, s, "P1", "取水口")
535		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
536		mustSample(t, s, "S1", "P1", at(2, 0), Measurement{Item: "pH", Value: 7})
537		mustSample(t, s, "S2", "P1", at(3, 0), Measurement{Item: "pH", Value: 9})
538	
539		if _, err := s.Void("S1", "   "); !errors.Is(err, ErrEmptyField) {
540			t.Fatalf("blank reason, got %v", err)
541		}
542		if _, err := s.Void("nope", "x"); !errors.Is(err, ErrUnknownSample) {
543			t.Fatalf("unknown sample, got %v", err)
544		}
545	
546		// 已确认样品作废后保留结果
547		if _, err := s.Confirm("S2"); err != nil {
548			t.Fatalf("Confirm S2: %v", err)
549		}
550		v, err := s.Void("S2", "  采样瓶破损  ")
551		if err != nil {
552			t.Fatalf("Void confirmed: %v", err)
553		}
554		if v.Status != StatusVoided || v.VoidReason != "采样瓶破损" || len(v.Results) != 1 || !v.Exceeded {
555			t.Fatalf("voided sample should keep results, got %+v", v)
556		}
557	
558		// 待判定样品作废后不能再确认
559		if _, err := s.Void("S1", "记录错误"); err != nil {
560			t.Fatalf("Void pending: %v", err)
561		}
562		if _, err := s.Confirm("S1"); !errors.Is(err, ErrVoided) {
563			t.Fatalf("confirm voided, got %v", err)
564		}
565	
566		// 重复作废：相同原因（去空白后）返回原记录，不同原因拒绝
567		if _, err := s.Void("S1", " 记录错误 "); err != nil {
568			t.Fatalf("same reason should return record, got %v", err)
569		}
570		if _, err := s.Void("S1", "别的原因"); !errors.Is(err, ErrVoidReasonConflict) {
571			t.Fatalf("different reason should be rejected, got %v", err)
572		}
573	
574		// 已作废样品的相同内容重报仍返回原样品，不同内容仍拒绝
575		if _, err := s.SubmitSample("S1", "P1", at(2, 0), Measurement{Item: "pH", Value: 7}); err != nil {
576			t.Fatalf("resubmit voided identical: %v", err)
577		}
578		if _, err := s.SubmitSample("S1", "P1", at(2, 0), Measurement{Item: "pH", Value: 8}); !errors.Is(err, ErrSampleConflict) {
579			t.Fatalf("resubmit voided different, got %v", err)
580		}
581	}
582	
583	func TestListAndLatest(t *testing.T) {
584		s, _ := open(t)
585		mustPoint(t, s, "P1", "取水口")
586		mustPoint(t, s, "P2", "排水口")
587		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
588		mustLimit(t, s, "P2", "pH", 8.0, at(1, 0))
589	
590		mustSample(t, s, "S2", "P1", at(5, 0), Measurement{Item: "pH", Value: 7})
591		mustSample(t, s, "S1", "P1", at(5, 0), Measurement{Item: "pH", Value: 7}) // 同时刻，编号升序
592		mustSample(t, s, "S3", "P1", at(8, 0), Measurement{Item: "pH", Value: 9})
593		mustSample(t, s, "S4", "P1", at(9, 0), Measurement{Item: "pH", Value: 7})
594		mustSample(t, s, "SX", "P2", at(10, 0), Measurement{Item: "pH", Value: 7})
595	
596		if _, err := s.Confirm("S3"); err != nil {
597			t.Fatalf("Confirm S3: %v", err)
598		}
599		if _, err := s.Void("S4", "作废"); err != nil {
600			t.Fatalf("Void S4: %v", err)
601		}
602	
603		list, err := s.ListByPoint("P1")
604		if err != nil {
605			t.Fatalf("ListByPoint: %v", err)
606		}
607		ids := []string{list[0].ID, list[1].ID, list[2].ID, list[3].ID}
608		want := []string{"S4", "S3", "S1", "S2"} // 时间晚到早，同时刻编号升序
609		for i := range want {
610			if ids[i] != want[i] {
611				t.Fatalf("order = %v, want %v", ids, want)
612			}
613		}
614		if list[1].Status != StatusConfirmed || !list[1].Exceeded {
615			t.Fatalf("S3 should be confirmed & exceeded: %+v", list[1])
616		}
617		if list[1].Results[0].Value != 9 || list[1].Results[0].Limit != 8.0 {
618			t.Fatalf("exceeded item should show value and limit: %+v", list[1].Results[0])
619		}
620		if list[0].Status != StatusVoided || list[2].Status != StatusPending {
621			t.Fatalf("statuses wrong: %+v", list)
622		}
623	
624		// 最近有效结果：跳过待判定与作废，取 S3
625		latest, ok, err := s.LatestResult("P1")
626		if err != nil || !ok || latest.ID != "S3" {
627			t.Fatalf("latest = %+v ok=%v err=%v", latest, ok, err)
628		}
629	
630		// 没有已确认且未作废的样品时明确无结果
631		if _, ok, err := s.LatestResult("P2"); err != nil || ok {
632			t.Fatalf("P2 should have no result, ok=%v err=%v", ok, err)
633		}
634	}
635	
636	func TestPersistenceAndIsolation(t *testing.T) {
637		s, dir := open(t)
638		mustPoint(t, s, "P1", "取水口")
639		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
640		mustSample(t, s, "S1", "P1", at(2, 0), Measurement{Item: "pH", Value: 9})
641		if _, err := s.Confirm("S1"); err != nil {
642			t.Fatalf("Confirm: %v", err)
643		}
644		if _, err := s.Void("S1", "复测"); err != nil {
645			t.Fatalf("Void: %v", err)
646		}
647		// 被拒绝的操作不留记录
648		if _, err := s.RegisterPoint("P1", "重复"); !errors.Is(err, ErrDuplicatePoint) {
649			t.Fatalf("dup point, got %v", err)
650		}
651		if err := s.Close(); err != nil {
652			t.Fatalf("Close: %v", err)
653		}
654	
655		// 重新打开同一目录：记录仍在
656		s2, err := Open(dir)
657		if err != nil {
658			t.Fatalf("reopen: %v", err)
659		}
660		defer s2.Close()
661		list, err := s2.ListByPoint("P1")
662		if err != nil || len(list) != 1 {
663			t.Fatalf("reopened list = %+v err=%v", list, err)
664		}
665		if list[0].Status != StatusVoided || list[0].VoidReason != "复测" || len(list[0].Results) != 1 {
666			t.Fatalf("reopened sample wrong: %+v", list[0])
667		}
668		if _, err := s2.RegisterPoint("P1", "再试"); !errors.Is(err, ErrDuplicatePoint) {
669			t.Fatalf("duplicate point after reopen, got %v", err)
670		}
671		if _, err := s2.Confirm("S1"); !errors.Is(err, ErrVoided) {
672			t.Fatalf("confirm voided after reopen, got %v", err)
673		}
674	
675		// 不同目录互不混用
676		s3, _ := open(t)
677		if _, err := s3.RegisterPoint("P1", "另一个P1"); err != nil {
678			t.Fatalf("other dir should be independent: %v", err)
679		}
680		if _, err := s3.Confirm("S1"); !errors.Is(err, ErrUnknownSample) {
681			t.Fatalf("other dir should not see S1, got %v", err)
682		}
683	}
